{"s13_law_citation_book_014","paper",2,"reg=law|hour=4,11|mood=funny",{1,"I wrote a citation this morning, habit, I guess",2,"For what?",1,"Fella doing seventy on 31W, handed it to him and he just looked at it - then he thanked me",2,"Thanked you?",1,"Said it was the most normal thing all week, then he drove off doing seventy"}},
{"s13_law_serve_papers_020","paper",2,"reg=law",{1,"I got civil papers to serve on a man out Echo Creek Road",2,"For what?",1,"Divorce, filed the second of July",2,"Serve 'em - let somebody's Tuesday finish out the way it was supposed to"}},
{"s13_law_paperwork_flood_040","paper",1,"reg=law|tmp=seasoned",{1,"Eleven offense reports on my desk and no place on this earth to send 'em",1,"Two complainants dead, one of the accused dead - one witness dead",1,"I'm finishing 'em anyway, rubber band around 'em, in the file drawer, where files go"}},
{"s13_ksp_notebook_names_004","paper",1,"reg=law|role=law_trooper|mood=grim",{1,"Page one is units, page two is people asking after people",1,"Page three I started for the ones I know are dead, so I quit writing 'em on page two",1,"I'd rather flip a page than tell somebody twice"}},
{"s13_ksp_case_number_010","paper",2,"reg=law|role=law_trooper",{1,"I'm still pulling case numbers off the block",2,"There's nobody to file 'em with",1,"There's a number on it and a number's got a date in it - ten years out that'll mean something"}},
{"s13_ksp_log_by_hand_015","paper",1,"reg=law|mood=grim",{1,"Radio operator kept the log in pencil, time, unit, what was said",1,"Last entry's 2:14 Sunday, unit 429 requesting assistance at the Ekron line",1,"There ain't a second line after it, she was writing and then she wasn't"}},
{"s13_ksp_license_photos_019","paper",2,"reg=law|world=vehicle",{1,"I've got a stack of license applications in the trunk with the photos still stapled on",2,"Why in the world?",1,"'Cause they've got names and faces on 'em, and I ain't the one who decides what's trash"}},
{"s13_ksp_abandoned_tags_031","paper",2,"reg=law|world=cars",{1,"I been chalking abandoned vehicles, date and my initials on the left rear",2,"That's a seventy-two hour tag",1,"It's a way of telling the next fella somebody already looked inside - that's all it is now"}},
{"s13_ksp_tape_recorder_039","paper",2,"reg=law",{1,"Took the little recorder off the dash, I talk into it at end of shift",2,"What for?",1,"Times, names, what I did, somebody's going to ask and I don't trust my head anymore"}},
{"s13_ksp_no_more_forms_041","paper",2,"reg=law",{1,"Ran out of the accident forms, the long ones with the diagram on the back",2,"Use notebook paper",1,"Drew the diagram on a menu off the diner at Riverside - skid marks and all"}},
{"s13_ksp_notebook_full_058","paper",2,"reg=law",{1,"Notebook's full, both covers, the margins, everything",2,"Get another one",1,"Did, took it off the shelf at the Sav Rite and left two dollars on a register with nobody at it"}},
{"s13_wire_log_the_order_014","paper",2,"reg=military|role=soldier_nco",{1,"Write it down, time, who said it, what it was",2,"Why? Nobody's coming to read it",1,"Somebody always comes to read it, eleven years I've watched somebody come read the book"}},
{"s13_wire_sector_sketch_031","paper",2,"reg=military|tmp=veteran|world=building",{1,"Range card's done, steeple at three hundred, culvert at one fifty, mailbox at ninety",2,"Why the mailbox?",1,"'Cause past the mailbox you're out of choices, and I'd rather have a number than a feeling"}},
{"s13_wire_absent_column_037","paper",2,"reg=military|mood=grim",{1,"Morning report's got a column for absent and a column for present",2,"And?",1,"There ain't a column for the other thing, so I been writing names in the margin"}},
{"s13_wire_civilians_names_043","paper",2,"reg=military|role=soldier_nco",{1,"Start writing the names of anybody we turn back",2,"Why?",1,"So when somebody says nobody was ever out here, there's a page that says different"}},
{"s13_wire_last_entry_058","paper",1,"reg=military|role=soldier_nco",{1,"Log's up to page nine, time, event, who - same as they taught me in 1981",1,"Page nine's mostly one line, nothing to report - nothing to report",1,"Day I ain't got that to write is the day I'd rather have already quit"}},
{"s13_eng_no_paperwork_023","paper",2,"reg=military|role=soldier_nco",{1,"There's a form for destroying a bridge, there's a form for everything",2,"You got it?",1,"I've got notebook paper with the grid, the time, how much we used, and my name at the bottom",1,"If that's the wrong paper, somebody can come tell me so"}},
{"s13_eng_ammo_accountability_024","paper",2,"reg=military|world=road",{1,"I signed for four hundred pound of explosive at the armory back in June",2,"And now?",1,"Now I've put two hundred and sixty of it into roads in my own county",1,"Hand receipt's still folded up in my cargo pocket, I don't know why I keep moving it"}},
{"s13_eng_grid_write_059","paper",2,"reg=military|tmp=veteran",{1,"Put the grid of every obstacle on one page and give it to two different people",2,"Why two?",1,"So whoever comes back through in the winter don't drive into our ditch in the dark"}},
{"fw_ld4_topics_a_0048","patrol_departure",2,"reg=law,swat",{1,"Radio check",2,"Loud and clear",1,"Ammo?",2,"Full",1,"Water?",2,"Two bottles",1,"Alright, let's go"}},
{"fw_ld4_topics_a_0049","patrol_departure",2,"reg=military,elite",{1,"Patrol leaves at 0600",2,"Yes sir",1,"Return by 1400",2,"And if we're late?",1,"Then we're late, don't die"}},
{"s10_patrol_jump_test_001","patrol_departure",3,"reg=military|tmp=seasoned,veteran|mood=calm",{1,"Everybody jump, right where you stand - twice",2,"Jump, Sergeant?",1,"Something rattled on Kowalczyk - find it before we step off",3,"Lighter in a mint tin, Sergeant - my fault",1,"Tape it or leave it here, out on that road a rattle carries a quarter mile"}},
{"s10_patrol_pump_house_shadow_002","patrol_departure",2,"reg=family|tmp=fresh,seasoned|day=5,90|mood=fear|world=water",{1,"If we're not back when the shadow hits the pump house, you bar the door and don't wait up",2,"And then what?",1,"Then come morning you take the kids to Aunt Ruth's by the creek road - not the highway",2,"You said all that last time",1,"And I came back last time, so it works - don't change anything"}},
{"s10_patrol_chalkboard_route_003","patrol_departure",2,"reg=law|tmp=seasoned,veteran|day=5,200|mood=grim|world=water",{1,"Put it on the board before we go, route, time out, who's in the car",2,"Nobody reads that board but us",1,"Then we'll know where to come looking for each other",2,"Out at {time}. {destination}, river road, two in the car - there",1,"Underline river road - Hollis never underlined, and we spent a whole day on the wrong one"}},
{"s10_patrol_chicken_man_004","patrol_departure",3,"reg=raider|tmp=predator|mood=funny",{1,"Truck leaves in five, anybody not on the tailgate stays back and scrubs pots",2,"Where we headed?",1,"{destination}, old boy with the chickens",3,"We hit him Tuesday, he ain't got chickens, we got his chickens",1,"Then we're going to see if he found more - get in the truck"}},
{"s10_patrol_leave_colors_005","patrol_departure",3,"reg=gang|tmp=predator,seasoned|mood=calm",{1,"Colors stay here, rag in your pocket, not on your head",2,"Then how's anybody know who we are?",1,"They don't, past {town}, everybody still breathing is scared of everybody",3,"Dead don't care what set you claim anyway",2,"Still feels like walking out naked"}},
{"s10_patrol_push_the_bikes_006","patrol_departure",3,"reg=club|hour=16,5|mood=funny",{1,"Nobody fires up till we're past the church - push 'em",2,"Push seven hundred pounds of bike a quarter mile?",1,"You want everything in {town} following your pipes home tonight? Push",3,"Should've put the quiet mufflers on like my old lady said",2,"Your old lady said a lot of things",3,"She was right about most of 'em - push"}},
{"s10_patrol_silo_rally_007","patrol_departure",3,"reg=elite|tmp=veteran|mood=calm",{1,"Comms check - two",2,"Two, good",1,"Three",3,"Three - weak",1,"Swap your battery, rally is the grain silo, if we split, we meet there at {time}, not one minute after",3,"And one minute after?",1,"One minute after, you're on your own, and you know the way home"}},
{"s10_patrol_sixteen_till_october_008","patrol_departure",2,"reg=family|tmp=fresh,seasoned|day=10,150|mood=sad",{1,"I'm going on the run to {destination}, I'm seventeen, that's old enough",2,"You're sixteen till October",1,"Danny was sixteen",2,"I know how old your brother was, you're hauling water with me today",1,"Every day it's water",2,"Every day you're here, you haul it"}},
{"s10_patrol_hard_hats_009","patrol_departure",3,"reg=worker|mood=funny",{1,"Hard hats on, I don't care how it looks",2,"A hard hat never stopped one of them",1,"Stopped a two-by-four off the scaffold on Larry's head in eighty-nine - things fall on patrols too",3,"Larry's head's got a dent in it anyway",1,"Larry's still got a head - hats on"}},
{"s10_patrol_lavender_slacks_010","patrol_departure",3,"reg=prison|mood=funny",{1,"Anybody still in county orange stays at camp, I'm not kidding",2,"I only got the one pair of pants",1,"Then you're guarding camp, folks see orange, they shoot first and read the stencil after",3,"Found him some church slacks in a closet on {street}",2,"They're lavender",1,"Lavender never got nobody shot - put 'em on"}},
{"s10_patrol_engine_or_brush_011","patrol_departure",2,"reg=rescue|role=rescue_firefighter,rescue_medical|day=7,120|mood=grim",{1,"Engine stays, we take the brush truck - the engine drinks a gallon every time you look at it",2,"Brush truck's got no room for a patient",1,"We haven't brought a patient back in nine days",2,"Then today's the day we'll need the room",1,"Fine, the engine, and nobody touches the siren switch, I don't care how bad your hand itches"}},
{"s10_patrol_route_blue_012","patrol_departure",2,"reg=military|tmp=seasoned,veteran|day=3,120|mood=funny",{1,"Lieutenant wants us on Route Blue, straight through the subdivision",2,"Route Blue has a cul-de-sac with forty of them standing in it",1,"On his map it's a through road",2,"His map was printed in nineteen seventy-eight",1,"So we take Route Blue as far as the cul-de-sac - after that we take whatever's real"}},
{"s10_patrol_long_rope_013","patrol_departure",2,"reg=outlaw,civilian|tmp=seasoned|mood=warm",{1,"Tie up the dog or she'll chase the truck",2,"She chases it every time, she always comes home",1,"Came home with half an ear last time",2,"Then use the long rope, she sulks on the short one"}},
{"s10_patrol_armored_vote_014","patrol_departure",3,"reg=swat|mood=funny|world=storm",{1,"We're taking the armored truck",2,"Four miles to the gallon, and it sounds like a thunderstorm with a hangover",1,"It also doesn't have a window anybody can reach through",3,"Put it to a vote",1,"Vests on, that's the vote - it passed"}},
{"s10_patrol_short_prayer_015","patrol_departure",3,"reg=civilian,family|day=5,300|mood=warm",{1,"Before we go, heads down, this'll be quick",2,"Pastor, the light's going",1,"Lord, bring back every one we send out - amen - that quick enough for you?",3,"That's the shortest one you ever did",1,"I'm saving the long ones for when we're all back at this table"}},
{"s10_patrol_same_gum_016","patrol_departure",3,"reg=military,law|tmp=fresh,seasoned|mood=funny",{1,"I'll take point",2,"You took point yesterday",1,"And nothing happened yesterday",3,"That isn't how luck works",1,"It's how mine's working, same boots, same order, same stick of gum since Monday",2,"Since Monday? Spit that out"}},
{"s10_patrol_cody_up_front_017","patrol_departure",3,"reg=raider,outlaw|tmp=predator,seasoned|mood=funny",{1,"Cody rides up front where I can see him",2,"I ain't running off",1,"You ran off from your own wedding, Cody",3,"Twice",2,"Second one don't count, preacher was drunk"}},
{"s10_patrol_hold_my_watch_018","patrol_departure",2,"reg=family|tmp=fresh,seasoned|day=3,200|mood=warm",{1,"Here - hold my watch till I'm back",2,"It's too big, it falls off my arm",1,"That's why you hold it, in your hand, all day - so it doesn't get lost",2,"When are you back?",1,"When the little hand's on the five, you keep an eye on it for me"}},
{"s10_patrol_trade_bag_count_019","patrol_departure",2,"reg=crime,gang|tmp=predator,seasoned|mood=angry",{1,"Who's carrying the trade bag?",2,"Me, boss",1,"Count it out loud, three bottles, two cartons, the gold watch",2,"You don't trust me?",1,"I trust you fine, I don't trust the story you'll tell me about the watch"}},
{"s10_patrol_same_number_back_020","patrol_departure",3,"reg=military|tmp=veteran,seasoned|day=5,300|mood=warm",{1,"Head count",2,"{count}, Sergeant",1,"We step off with {count}, we walk back in with {count} - any other number, somebody owes me a reason",3,"What if it's more? What if we find somebody?",1,"Then that's a good reason"}},
{"s10_patrol_four_day_biscuits_021","patrol_departure",3,"reg=family,civilian|tmp=seasoned|day=10,200|mood=warm",{1,"Mamaw packed biscuits for the run",2,"We're going four miles",1,"She packed for four days",3,"Let her, the one time she didn't, the Tanner boys spent the night locked in the feed store",2,"Glovebox, then - and tell her thanks for me"}},
{"s10_patrol_pen_not_pencil_022","patrol_departure",1,"reg=civilian,worker|tmp=seasoned|day=5,300|mood=calm",{1,"Knife - water - hammer, matches in the sandwich bag",1,"Note on the table says where I went. {destination}, back by dark",1,"Wrote it in pen this time, pencil smeared the last one to nothing"}},
